// Content generated by AI is identified separately from verified local examples.
import {FOREIGN_LANGUAGES,FOREIGN_LEVELS,FOREIGN_TOPICS,CLASSICAL_LEVELS,FOREIGN_PHRASES,ANCIENT_GREEK_PHRASES} from './foreign_languages_curriculum.mjs';
export const MODERN_OUTCOMES={
 A1:['Recunoaște formule familiare și expresii cotidiene.','Construiește propoziții foarte scurte despre identitate și necesități.','Răspunde la întrebări simple cu sprijin.'],
 A2:['Înțelege mesaje scurte despre rutină și cumpărături.','Descrie trecutul, prezentul și planurile apropiate.','Susține schimburi scurte în situații previzibile.'],
 B1:['Explică experiențe, planuri și opinii.','Înțelege ideea principală din discurs clar.','Scrie texte coerente pe teme familiare.'],
 B2:['Argumentează avantaje și dezavantaje.','Participă la discuții mai complexe.','Înțelege texte autentice cu registre diferite.'],
 C1:['Înțelege nuanțe și sensuri implicite.','Construiește argumentații bine structurate.','Adaptează registrul academic și profesional.'],
 C2:['Interpretează subtilități de sens și registru.','Sintetizează critic surse diverse.','Produce discurs fluent și precis în contexte exigente.']
};
export const CLASSICAL_OUTCOMES={
 foundation:['Identifică alfabetul și pronunția convențională.','Recunoaște morfeme, cazuri și forme verbale introductive.','Traduce expresii scurte în context.'],
 grammar:['Analizează morfologia și sintaxa propozițiilor.','Justifică opțiuni de traducere folosind contextul.','Distinge genuri și registre istorice.'],
 advanced:['Analizează filologic surse și variante textuale.','Compară particularitățile stilistice și istorice.','Discută interpretări critice și limite de reconstrucție.']
};
export const TOPIC_GOALS={
 alphabet:['grafeme și sunete','ortografie și citire','corespondențe scriere–pronunție'],
 greetings:['saluturi, politețe și context social','registre formale și informale','răspunsuri corecte în situații sociale'],
 vocabulary:['câmp lexical și colocation','utilizarea cuvintelor în propoziții','parafrazare și relații semantice'],
 grammar:['categorii gramaticale și acord','timpuri, aspect și mod','structuri complexe după nivel'],
 listening:['recunoașterea sunetelor','mesaj oral și sens global','detalii și inferențe din dialog'],
 conversation:['dialog cu replici scurte','clarificare și negociere de sens','conversație spontană în context'],
 reading:['idei principale și detalii','traducere contextuală','inferențe și analiză textuală'],
 assessment:['evaluare formativă cu explicații','recapitularea greșelilor','stabilirea obiectivelor următoare']
};
export function foreignStudyCourseMap(){
 return FOREIGN_LANGUAGES.map(language=>({
  language:language.id,
  variants:(language.variants.length?language.variants:['standard']).map(variant=>{
   const classical=language.id==='la'||language.id==='el'&&['ancient','koine'].includes(variant);
   return {variant,levels:(classical?CLASSICAL_LEVELS:FOREIGN_LEVELS).map(x=>x.id),
     topics:FOREIGN_TOPICS.map(x=>x.id)};
  })
 }));
}
export function foreignStudyPlan(language,variant,level,topic){
 const lang=FOREIGN_LANGUAGES.find(x=>x.id===language);
 const classical=language==='la'||language==='el'&&['ancient','koine'].includes(variant);
 const levels=classical?CLASSICAL_LEVELS:FOREIGN_LEVELS;
 if(!lang||!levels.some(l=>l.id===level)||!FOREIGN_TOPICS.some(t=>t.id===topic))return null;
 const goals=classical?CLASSICAL_OUTCOMES[level]:MODERN_OUTCOMES[level];
 const variants=lang.variants.length?lang.variants:['standard'];
 if(!variants.includes(variant||'standard'))return null;
 return {language,variant:variant||'standard',level,topic,mode:classical?'classical':'modern',
   goals:[...goals],topicGoals:[...TOPIC_GOALS[topic]],
   lessonSections:['obiective','explicații','vocabular original/fonetic/traducere','reguli și exemple','practică ghidată','evaluare','recapitulare'],
   exercises:topic==='listening'?['ascultă și transcrie','înțelegere orală','întrebări despre dialog']:
   topic==='conversation'?['dialog cu AI','răspunde și reformulează','corectură contextuală']:
   topic==='assessment'?['întrebări gradate','argumentarea răspunsului','feedback și reluare']:
   ['alegere multiplă','completare','traducere contextuală','producere liberă'],
   phonetics:language==='zh'?'Pinyin tonal':language==='ja'?'Rōmaji și kana':classical?'transliterare și pronunție reconstruită':'IPA în varianta regională corectă'};
}
export function foreignStudyRubric(level,classical=false){
 return {level,criteria:classical?['precizia morfologică','analiză sintactică','contextul traducerii','argumentare filologică']:
  ['înțelegere','vocabular','gramatică','coerență','adecvarea la context'],
  assessment:'formative',certified:false};
}
export function foreignStudyReview(previous={},correct=false,at=Date.now()){
 const old=previous&&typeof previous==='object'?previous:{};
 const streak=correct?Math.min(12,(Number(old.streak)||0)+1):0;
 const intervals=[0,1,3,7,14,30,60,90,120,180,240,365,365];
 const days=correct?intervals[streak]:0;
 return {correct:!!correct,streak,attempts:(Number(old.attempts)||0)+1,
  lastReviewed:at,due:correct?at+days*86400000:at,intervalDays:days};
}
export function foreignStudyDue(progress,now=Date.now()){
 return Object.entries(progress||{}).filter(([,v])=>v&&Number(v.due||0)<=now).map(([id])=>id);
}
export function foreignStudyPlacementQuestions(language,variant){
 const classical=language==='la'||language==='el'&&['ancient','koine'].includes(variant);
 const cards=classical&&language==='el'?ANCIENT_GREEK_PHRASES:FOREIGN_PHRASES[language]||[];
 return cards.slice(0,6).map((card,i)=>({id:card.id,question:card.meaning,answer:card.original,
  diagnosticOnly:true,level:classical?'foundation':'A1',index:i}));
}
export function foreignStudyPlacementResult(answers,questions,classical=false){
 const q=Array.isArray(questions)?questions:[],responses=Array.isArray(answers)?answers:[];
 const clean=x=>String(x||'').normalize('NFKC').toLowerCase().replace(/[!?.,;:]/g,'').replace(/\s+/g,' ').trim();
 const correct=q.filter((item,i)=>clean(responses[i])===clean(item.answer)).length;
 return {correct,total:q.length,percent:q.length?Math.round(correct*100/q.length):0,
  recommendation:classical?'foundation':'A1',certified:false,
  notice:'Test introductiv din vocabularul de bază; nu determină singur nivelul CEFR. Pentru o recomandare superioară este necesară evaluare extinsă.'};
}
